-- Preserve existing bonus values; widen only numeric bonus columns.
-- Applied and verified on the configured player schema on 2026-11-10.
-- item_proto.applyvalue0..4 already use DECIMAL(10,3) and are unchanged.
-- Keep existing nullability, defaults, unsigned attributes, and keys.
SET SESSION sql_mode = 'STRICT_ALL_TABLES,NO_ENGINE_SUBSTITUTION';
SET SESSION lock_wait_timeout = 20;
USE `player`;

ALTER TABLE `item` MODIFY COLUMN `attrvalue0` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue1` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue2` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue3` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue4` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue5` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue6` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue7` decimal(13,3) NOT NULL DEFAULT 0;
ALTER TABLE `account_mount_inventory` MODIFY COLUMN `attrvalue0` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue1` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue2` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue3` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue4` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue5` decimal(13,3) NULL DEFAULT 0, MODIFY COLUMN `attrvalue6` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue7` decimal(13,3) NOT NULL DEFAULT 0;
ALTER TABLE `item_award` MODIFY COLUMN `attrvalue0` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue1` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue2` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue3` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue4` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue5` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue6` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `attrvalue7` decimal(13,3) NOT NULL DEFAULT 0;
ALTER TABLE `affect` MODIFY COLUMN `lApplyValue` decimal(13,3) NOT NULL DEFAULT 0;
ALTER TABLE `item_attr` MODIFY COLUMN `lv1` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv2` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv3` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv4` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv5` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv1_costume` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv2_costume` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv3_costume` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv4_costume` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv5_costume` decimal(13,3) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `item_attr_rare` MODIFY COLUMN `lv1` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv2` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv3` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv4` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv5` decimal(13,3) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `item_attr_rare_8` MODIFY COLUMN `lv1` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv2` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv3` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv4` decimal(13,3) unsigned NOT NULL DEFAULT 0, MODIFY COLUMN `lv5` decimal(13,3) unsigned NOT NULL DEFAULT 0;
ALTER TABLE `item_extra_proto` MODIFY COLUMN `bonus_value0` decimal(13,3) NOT NULL DEFAULT 0, MODIFY COLUMN `bonus_value1` decimal(13,3) NOT NULL DEFAULT 0;
